declare a clob;n number;begin dbms_lob.createtemporary(a,true);for s in(select TEXT from USER_SOURCE where NAME='RRL_ASSEMBLY_SCALE_API'and TYPE='PACKAGE BODY'order by LINE)loop dbms_lob.append(a,replace(s.TEXT,chr(13),''));end loop;if rawtohex(sys.dbms_crypto.hash(a,sys.dbms_crypto.hash_sh256))!='F785EA4A93151725E712ACC957A98E2B97296915D3D652D0F0068FF5D9F0F815'then raise_application_error(-20886,'ASM_SHIPPING_CONTEXT_SOURCE_MISMATCH');end if;select count(*)into n from USER_OBJECTS where STATUS='INVALID';if n!=0 then raise_application_error(-20886,'ASM_SHIPPING_CONTEXT_INVALID_BEFORE');end if;end;
